examples.template:
Button {
    isOpen = true
} label: {
    HStack {
        Text(options.first { $0.value == status }?.label ?? {{label}})
            .monarchTextStyle(.body)
            .foregroundStyle(theme.colors.textDefault)
        Spacer(minLength: 0)
        Image(systemName: "chevron.down")
            .imageScale(.small)
            .foregroundStyle(theme.colors.textMuted)
    }
    .padding(.horizontal, theme.spacing.space3)
    .frame(minHeight: 44)
    .background(theme.colors.bgSurface, in: RoundedRectangle(cornerRadius: MonarchTokens.Radius.md, style: .continuous))
    .overlay(RoundedRectangle(cornerRadius: MonarchTokens.Radius.md, style: .continuous).strokeBorder(theme.colors.borderDefault, lineWidth: MonarchTokens.Space.px))
    .contentShape(Rectangle())
}
.buttonStyle(.plain)
.accessibilityLabel({{label}})
.accessibilityValue(options.first { $0.value == status }?.label ?? "")
.frame(width: 224)
.onAppear { if startsPresented { isOpen = true } }
.popover(isPresented: $isOpen, arrowEdge: .top) {
    VStack(alignment: .leading, spacing: 0) {
        ForEach(options, id: \.value) { option in
            Button {
                status = option.value
                isOpen = false
            } label: {
                HStack {
                    Text(option.label).monarchTextStyle(.body)
                    Spacer(minLength: theme.spacing.space4)
                    if status == option.value {
                        Image(systemName: "checkmark").foregroundStyle(theme.colors.accentSolid)
                    }
                }
                .foregroundStyle(theme.colors.textDefault)
                .padding(.horizontal, theme.spacing.space3)
                .frame(minHeight: 44)
                .background(status == option.value ? theme.colors.bgMuted : Color.clear, in: RoundedRectangle(cornerRadius: MonarchTokens.Radius.md, style: .continuous))
                .contentShape(Rectangle())
            }
            .buttonStyle(.plain)
            .accessibilityAddTraits(status == option.value ? .isSelected : [])
        }
    }
    .padding(theme.spacing.space1)
    .frame(minWidth: 224)
    .presentationCompactAdaptation(.popover)
    .presentationBackground(theme.colors.bgSurface)
}

examples.setupTemplate:
@Environment(\.monarchTheme) private var theme
@Environment(\.monarchStartsPresented) private var startsPresented
@State private var isOpen = false
@State private var status = {{selected}}
private let options = [
    (value: {{options.0.value}}, label: {{options.0.label}}),
    (value: {{options.1.value}}, label: {{options.1.label}}),
    (value: {{options.2.value}}, label: {{options.2.label}}),
]

